[6] = {id = 6, activityid = 46000, version = 1, role = 10009, gift = "4_60003005_1", type = 1, award = "1_100000_50,1_120005_1,1_100001_5000", plot = "qingrenjie/qingrenjie_mogenlefei", text = "0"},
[7] = {id = 7, activityid = 46000, version = 1, role = 11014, gift = "4_60003005_1", type = 1, award = "1_100000_50,1_120006_1,1_100001_5000", plot = "qingrenjie/qingrenjie_sikadi", text = "0"},
[8] = {id = 8, activityid = 46000, version = 2, role = 13003, gift = "4_60003004_1", type = 0, award = "1_100000_150,1_110120_1,1_100001_5000", plot = "0", text = "\u{3000}\u{3000}謝謝你的蛋糕。蛋糕特別好吃，第一口吃的時候，我是真沒想到能嘗到甜味。你知道的，宿醉後舌頭總是像是糊了一層麵粉，嘗不出味兒。拖蛋糕的福，頭疼也減輕了不少。我要拿出藏起來的好酒，試一試就著蛋糕喝酒是什麼滋味。"},
[9] = {id = 9, activityid = 46000, version = 2, role = 13021, gift = "4_60003004_1", type = 0, award = "1_100000_150,1_110120_1,1_100001_5000", plot = "0", text = "\u{3000}\u{3000}今天一大早，我就在神社門口等著你的蛋糕了。通過占卜，我早就知道了一切。可你知道嗎？過早的甜蜜往往預示著未來的酸鹹。看來今天晚飯必須吃酸湯豚骨拉麵了。"},
[10] = {id = 10, activityid = 46000, version = 2, role = 10018, gift = "4_60003004_1", type = 0, award = "1_100000_150,1_110120_1,1_100001_5000", plot = "0", text = "\u{3000}\u{3000}沒想到領航竟然會製作蛋糕。哈哈，我也正好在嘗試製作新的蛋糕樣式，這是為了下一次的生日做準備。嘗過了你的蛋糕，我感受到一些啟發。等我做完後，也送給你嘗嘗吧，我們互相交流，互相進步。"},
[11] = {id = 11, activityid = 46000, version = 3, role = 11015, gift = "4_60003004_1", type = 0, award = "1_100000_150,1_110120_1,1_100001_5000", plot = "0", text = "\u{3000}\u{3000}領航做的蛋糕鈴收到啦！香香甜甜，美味無比。就算天才如我，也沒法做得更好了。領航就是做蛋糕的天才！"},
[12] = {id = 12, activityid = 46000, version = 3, role = 10005, gift = "4_60003004_1", type = 0, award = "1_100000_150,1_110120_1,1_100001_5000", plot = "0", text = "\u{3000}\u{3000}收到領航的禮物，小生受寵若驚。從蛋糕的甜膩中，小生感受到了領航的心意。看來領航已經準備好接受小生全力的踢擊了吧。"},
[13] = {id = 13, activityid = 46000, version = 3, role = 12001, gift = "4_60003004_1", type = 0, award = "1_100000_150,1_110120_1,1_100001_5000", plot = "0", text = "\u{3000}\u{3000}謝謝你啊，領航。雖然能收到你的禮物我很高興啦，但最近蛋糕啊、布丁啊這類甜食吃得實在是太多了，我一看到蛋糕就……不過我還是會全部吃乾淨的哦，把領航的蛋糕全部吃~幹~淨~。"},
